import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import ts from 'typescript';
const src=fs.readFileSync('src/lib/openJobCurrentCostProjection.ts','utf8');
const module={exports:{}};
vm.runInNewContext(ts.transpileModule(src,{compilerOptions:{module:ts.ModuleKind.CommonJS}}).outputText,{module,exports:module.exports});
const {projectOpenJobCurrentCosts}=module.exports;
const lines=[{productId:'a',quantity:4,soldUnitPrice:200,quotedUnitCost:80,orderedQuantity:2,orderedUnitCost:90}];
const original=JSON.stringify(lines);
const result=projectOpenJobCurrentCosts(lines,new Map([['a',110]]));
assert.equal(result.revenue,800);
assert.equal(result.quotedCost,320);
assert.equal(result.projectedCost,400);
assert.equal(result.projectedGrossProfit,400);
assert.equal(result.projectedMarginPercent,50);
assert.equal(result.unverifiedUnits,0);
assert.equal(JSON.stringify(lines),original);
const missing=projectOpenJobCurrentCosts(lines,new Map());
assert.equal(missing.projectedCost,340);
assert.equal(missing.unverifiedUnits,2);
assert.throws(()=>projectOpenJobCurrentCosts([{...lines[0],orderedQuantity:5}],new Map()),/Invalid/);
assert.throws(()=>projectOpenJobCurrentCosts([{...lines[0],orderedUnitCost:null}],new Map()),/committed/);
console.log('Open job current-cost projection tests passed');
